final class RecordingSession {
    let id: Int
    init(id: Int) { self.id = id }
    deinit { print("Освобождена сессия \(id)") }
}
var first: RecordingSession? = RecordingSession(id: 31) // 1
var second = first // 2
var saved: (() -> Void)? = { [session = first!] in // 3
    print(session.id)
}
first = nil // 2: second и захват
second = nil // 1: захват
saved?() // 1: захват
saved = nil // 0: deinit
print("Готово")

Цепочка: 1 → 2 → 3 → 2 → 1 → 1 → 0. Числа описывают владельцев в исходнике; это не показания внутреннего счётчика ARC.

