final class RecordingSession {
    let id: Int
    init(id: Int) { self.id = id }
    deinit { print("Освобождена сессия \(id)") }
}
var session: RecordingSession? = RecordingSession(id: 32)
var pending: [RecordingSession] = [session!]
session = nil
print(pending[0].id)
pending.removeAll()
print("Очередь очищена")

После session = nil остаётся один видимый владелец: элемент pending. removeAll убирает его; в этом примере других владельцев нет.

final class RecordingBuffer {
    let sampleCount: Int
    init(sampleCount: Int) { self.sampleCount = sampleCount }
    deinit { print("Буфер освобождён") }
}
func makeReader(sampleCount: Int) -> () -> Void {
    let buffer = RecordingBuffer(sampleCount: sampleCount)
    return { print(buffer.sampleCount) }
}
var reader: (() -> Void)? = makeReader(sampleCount: 128)
reader?()
reader = nil
print("Чтение завершено")

Вывод: 128, «Буфер освобождён», «Чтение завершено». Возвращённое замыкание удерживает буфер после возврата makeReader; очистка reader убирает этот захват.
